package Thumbnail;
use strict;
use warnings;

sub _trim {
    my ($s) = @_;
    $s =~ s/^\s+|\s+$//g;
    return $s;
}

sub make_thumbnail {
    my ($src, $dst) = @_;
    system("convert " . _trim($src) . " -resize 128x128 $dst") == 0 or die "convert failed";
    return $dst;
}

1;
